class Solution:
    def maxDifference(self, s: str) -> int:
        # Count frequency of each character
        freq = {}
        for char in s:
            freq[char] = freq.get(char, 0) + 1

        # Separate odd and even frequencies
        odd_freqs = [f for f in freq.values() if f % 2 == 1]
        even_freqs = [f for f in freq.values() if f % 2 == 0]

        # Find maximum difference: max odd freq - min even freq
        # Since constraints guarantee at least one odd and one even frequency
        max_diff = 0
        for o in odd_freqs:
            for e in even_freqs:
                diff = o - e
                if diff > max_diff:
                    max_diff = diff

        return max_diff
