class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        if not grid or not grid[0]:
            return []

        m = len(grid)  # number of rows
        n = len(grid[0])  # number of columns

        result = []
        skip = False  # flag to indicate if the next cell should be skipped

        for i in range(m):
            if i % 2 == 0:
                # Traverse right
                for j in range(n):
                    if not skip:
                        result.append(grid[i][j])
                    skip = not skip
            else:
                # Traverse left
                for j in range(n - 1, -1, -1):
                    if not skip:
                        result.append(grid[i][j])
                    skip = not skip

        return result
