class Solution:
    def subarraySum(self, nums: List[int]) -> int:
        n = len(nums)
        total_sum = 0
        for i in range(n):
            start = max(0, i - nums[i])
            # Sum the subarray from start to i (inclusive)
            for j in range(start, i + 1):
                total_sum += nums[j]
        return total_sum
