def main():
    s1, s2 = input().split()

    # Takahashi ate 1 and 2
    # Aoki ate 1 and 3

    # If Takahashi is sick, then the bad oyster is either 1 or 2.
    # If Aoki is sick, then the bad oyster is either 1 or 3.

    # Let's analyze:
    # Case 1: s1 == "sick" and s2 == "sick"
    #   Takahashi sick => bad in {1,2}
    #   Aoki sick => bad in {1,3}
    #   Intersection is {1}. So bad oyster is 1.

    # Case 2: s1 == "sick" and s2 == "fine"
    #   Takahashi sick => bad in {1,2}
    #   Aoki fine => bad not in {1,3} => bad is not 1 and not 3.
    #   So bad is not 1. From {1,2}, remove 1 => bad is 2.

    # Case 3: s1 == "fine" and s2 == "sick"
    #   Takahashi fine => bad not in {1,2} => bad is not 1 and not 2.
    #   Aoki sick => bad in {1,3}
    #   Since bad is not 1, from {1,3} we get bad is 3.

    # Case 4: s1 == "fine" and s2 == "fine"
    #   Takahashi fine => bad not in {1,2}
    #   Aoki fine => bad not in {1,3}
    #   So bad is not 1, 2, or 3. Therefore bad is 4.

    if s1 == "sick" and s2 == "sick":
        print(1)
    elif s1 == "sick" and s2 == "fine":
        print(2)
    elif s1 == "fine" and s2 == "sick":
        print(3)
    else:  # both fine
        print(4)

