class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        n = len(nums)
        # If k is greater than the length of nums, there are no subarrays of size k
        if k > n:
            return -1

        # Dictionary to count how many subarrays of size k each number appears in
        count = {}

        # Iterate over all subarrays of size k
        for i in range(n - k + 1):
            subarray = nums[i:i+k]
            # For each element in the subarray, increment its count
            for num in subarray:
                count[num] = count.get(num, 0) + 1

        # Find the largest integer that appears in exactly one subarray
        result = -1
        for num, cnt in count.items():
            if cnt == 1:
                if num > result:
                    result = num

        return result
