class Solution:
    def minimumPairRemoval(self, nums: List[int]) -> int:
        def is_non_decreasing(arr):
            for i in range(1, len(arr)):
                if arr[i] < arr[i-1]:
                    return False
            return True

        # If already non-decreasing, return 0
        if is_non_decreasing(nums):
            return 0

        # We need to simulate the process
        # Since the array length is small (<=50), we can simulate step by step
        arr = nums[:]
        ops = 0
        while not is_non_decreasing(arr):
            # Find the adjacent pair with the minimum sum, leftmost if tie
            min_sum = float('inf')
            min_idx = -1
            for i in range(len(arr) - 1):
                s = arr[i] + arr[i+1]
                if s < min_sum:
                    min_sum = s
                    min_idx = i
            # Replace the pair at min_idx with their sum
            arr[min_idx] = arr[min_idx] + arr[min_idx+1]
            arr.pop(min_idx + 1)
            ops += 1
        return ops
